	/**
	 * Default Constructor
	 */
    public ApplicationService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ApplicationEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ApplicationRepository.class) );
		this.validator		= applicationContext.getBean(ApplicationValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Application
	 */
		public Application createApplication( CreateApplicationCommand command ) {

		Application entity = new Application();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setApplicationId( command.getApplicationId() );
            entity.setApplicationNumber( command.getApplicationNumber() );
            entity.setSubmissionDate( command.getSubmissionDate() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Application {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateApplicationCommand
	 * @return		Application
	 */
	public Application updateApplication( UpdateApplicationCommand command ) {

		Application entity = new Application();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setApplicationId( command.getApplicationId() );
            entity.setApplicationNumber( command.getApplicationNumber() );
            entity.setSubmissionDate( command.getSubmissionDate() );
            entity.setCustomer( command.getCustomer() );
            entity.setProduct( command.getProduct() );
            entity.setDistributor( command.getDistributor() );
            entity.setQuotes( command.getQuotes() );
            entity.setSelectedQuote( command.getSelectedQuote() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Application {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteApplicationCommand
	 */
	public void delete( DeleteApplicationCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getApplicationId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Application {0} ", id );

	}

	/**
	 * Method to retrieve the Application via ApplicationFetchOneSummary
	 * @param 	summary ApplicationFetchOneSummary
	 * @return 	ApplicationFetchOneResponse
	 */
	public Application getApplication( ApplicationFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ApplicationFetchOneSummary arg cannot be null" );

		Application entity = null;
		UUID id = summary.getApplicationId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Application using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Applications
	 *
	 * @return 	List<Application>
	 */
    public List<Application> getAllApplication() {
		List<Application> list = projector.findAll( new FindAllApplicationQuery() );
		return list;
	}

	/**
	 * assign Customer on Application
	 * @param		command AssignCustomerToApplicationCommand
	 */
	public void assignCustomer( AssignCustomerToApplicationCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCustomer(command.getApplicationId(), command.getAssignment());

	}

